<?php
declare(strict_types=1);
function adm_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function adm_start(string $page,string $active='dashboard',bool $login=false):void{?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=adm_h($page)?> · Restaurante da Bia</title><?php $adminFavicon=\App\Cms::setting('favicon');$adminLogo=\App\Cms::setting('logo');if($adminFavicon):?><link rel="icon" href="<?=adm_h($adminFavicon)?>"><?php endif;?><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyTSlDJQToswBJ4EyH+8aBaAZG7D" crossorigin="anonymous"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/admin.css"></head><body class="<?=$login?'auth-body':'admin-body'?>">
<?php if(!$login):?><div class="admin-shell"><aside class="sidebar offcanvas-lg offcanvas-start" tabindex="-1" id="adminSidebar"><div class="offcanvas-header d-lg-none"><h5 class="offcanvas-title">Menu</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="offcanvas" data-bs-target="#adminSidebar" aria-label="Fechar"></button></div><div class="offcanvas-body d-flex flex-column p-0"><a class="admin-brand" href="/admin/"><?php if($adminLogo):?><img class="admin-custom-logo" src="<?=adm_h($adminLogo)?>" alt="Restaurante da Bia"><?php else:?><span class="brand-icon">B.</span><span>Restaurante <strong>da Bia</strong><small>PAINEL DE GESTÃO</small></span><?php endif;?></a><div class="sidebar-section">GERENCIAMENTO</div><nav class="side-nav"><a class="<?=$active==='dashboard'?'active':''?>" href="/admin/"><i class="bi bi-grid-1x2"></i> Visão geral</a><a class="<?=$active==='orders'?'active':''?>" href="/admin/#pedidos"><i class="bi bi-bag-check"></i> Pedidos</a><a class="<?=$active==='reservations'?'active':''?>" href="/admin/#reservas"><i class="bi bi-calendar2-check"></i> Reservas</a><a class="<?=$active==='payments'?'active':''?>" href="/admin/payments.php"><i class="bi bi-credit-card"></i> Pagamentos</a><a class="<?=$active==='pages'?'active':''?>" href="/admin/pages.php"><i class="bi bi-file-earmark-text"></i> Páginas</a><a class="<?=$active==='gallery'?'active':''?>" href="/admin/gallery.php"><i class="bi bi-images"></i> Galeria</a><a class="<?=$active==='settings'?'active':''?>" href="/admin/settings.php"><i class="bi bi-gear"></i> Configurações</a></nav><div class="sidebar-section mt-4">ACESSO RÁPIDO</div><nav class="side-nav"><a href="/" target="_blank" rel="noopener"><i class="bi bi-box-arrow-up-right"></i> Ver site público</a></nav><div class="sidebar-bottom"><span class="status-dot"></span> Ambiente demonstrativo</div></div></aside><div class="admin-main"><div class="admin-topbar"><button class="btn btn-outline-secondary d-lg-none" data-bs-toggle="offcanvas" data-bs-target="#adminSidebar" aria-label="Abrir navegação"><i class="bi bi-list"></i></button><span class="crumb">Restaurante da Bia <i class="bi bi-chevron-right mx-2"></i> <?=adm_h($page)?></span><a href="/admin/settings.php" class="admin-avatar" title="Identidade visual"><?php if($adminLogo):?><img src="<?=adm_h($adminLogo)?>" alt="Logo"><?php else:?>AD<?php endif;?></a></div><div class="admin-content"><?php endif;?>
<?php }
function adm_end(bool $login=false):void{if(!$login):?></div></div></div><?php endif;?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js" integrity="sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz" crossorigin="anonymous"></script><script>
document.addEventListener('DOMContentLoaded',function(){
 const menu=document.getElementById('adminSidebar');
 document.querySelectorAll('[data-bs-target="#adminSidebar"]').forEach(function(btn){
  btn.addEventListener('click',function(){if(!window.bootstrap){menu.classList.toggle('is-open');}});
 });
 document.querySelectorAll('.side-nav a').forEach(function(a){
  a.addEventListener('click',function(){menu?.classList.remove('is-open')});
 });
});
</script></body></html><?php }
function adm_status(string $status):string{$labels=['pending'=>'Pendente','accepted'=>'Aceito','preparing'=>'Em preparo','ready'=>'Pronto','dispatched'=>'Em entrega','completed'=>'Concluído','cancelled'=>'Cancelado','paid'=>'Pago','confirmed'=>'Confirmada','failed'=>'Falhou','refunded'=>'Reembolsado'];$colors=['pending'=>'warning','accepted'=>'info','preparing'=>'info','ready'=>'primary','dispatched'=>'primary','completed'=>'success','paid'=>'success','confirmed'=>'success','cancelled'=>'danger','failed'=>'danger','refunded'=>'secondary'];return '<span class="badge rounded-pill text-bg-'.($colors[$status]??'secondary').'">'.adm_h($labels[$status]??$status).'</span>';}
